CREATE TABLE IF NOT EXISTS cms_forms(id BIGSERIAL PRIMARY KEY,form_key VARCHAR(190) NOT NULL UNIQUE,label TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),settings_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_form_fields(id BIGSERIAL PRIMARY KEY,form_id BIGINT NOT NULL REFERENCES cms_forms(id) ON DELETE CASCADE,field_key VARCHAR(190) NOT NULL,label TEXT NOT NULL,field_type VARCHAR(40) NOT NULL,required BOOLEAN NOT NULL DEFAULT FALSE,position INTEGER NOT NULL DEFAULT 0,validation_json TEXT NOT NULL DEFAULT '{}',settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(form_id,field_key));
CREATE TABLE IF NOT EXISTS cms_form_submissions(id BIGSERIAL PRIMARY KEY,form_id BIGINT NOT NULL REFERENCES cms_forms(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'new' CHECK(status IN('new','processing','completed','rejected')),payload_json TEXT NOT NULL,source_ip_hash VARCHAR(64) NOT NULL DEFAULT '',user_agent_hash VARCHAR(64) NOT NULL DEFAULT '',submitted_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cms_form_submissions_form ON cms_form_submissions(form_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS cms_custom_field_definitions(id BIGSERIAL PRIMARY KEY,field_key VARCHAR(190) NOT NULL UNIQUE,label TEXT NOT NULL,entity_type VARCHAR(80) NOT NULL,field_type VARCHAR(40) NOT NULL,validation_json TEXT NOT NULL DEFAULT '{}',settings_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_custom_field_values(field_id BIGINT NOT NULL REFERENCES cms_custom_field_definitions(id) ON DELETE CASCADE,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT NOT NULL,value_json TEXT NOT NULL DEFAULT 'null',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(field_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS cms_workflows(id BIGSERIAL PRIMARY KEY,workflow_key VARCHAR(190) NOT NULL UNIQUE,label TEXT NOT NULL,entity_type VARCHAR(80) NOT NULL,initial_state VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_workflow_transitions(id BIGSERIAL PRIMARY KEY,workflow_id BIGINT NOT NULL REFERENCES cms_workflows(id) ON DELETE CASCADE,from_state VARCHAR(80) NOT NULL,to_state VARCHAR(80) NOT NULL,permission_key VARCHAR(120) NOT NULL DEFAULT '',conditions_json TEXT NOT NULL DEFAULT '{}',actions_json TEXT NOT NULL DEFAULT '[]',UNIQUE(workflow_id,from_state,to_state));
CREATE TABLE IF NOT EXISTS cms_workflow_events(id BIGSERIAL PRIMARY KEY,workflow_id BIGINT NOT NULL REFERENCES cms_workflows(id) ON DELETE CASCADE,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT NOT NULL,from_state VARCHAR(80),to_state VARCHAR(80) NOT NULL,actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL,payload_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_automation_recipes(id BIGSERIAL PRIMARY KEY,recipe_key VARCHAR(190) NOT NULL UNIQUE,label TEXT NOT NULL,trigger_event VARCHAR(190) NOT NULL,conditions_json TEXT NOT NULL DEFAULT '{}',actions_json TEXT NOT NULL DEFAULT '[]',is_enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_migrations(version) VALUES('10.18.0') ON CONFLICT(version) DO NOTHING;